/* Remove redundant, nearly parallel strokes at the prepared view, without frame-by-frame popping. */
window.filterAtlasSketchEdges=async function(THREE,lines,camera,width,height,gap=5){
 camera.updateMatrixWorld(true);let count=0;for(const line of lines)count+=line.geometry.attributes.position.count/2;
 const points=new Float32Array(count*4),lengths=new Float32Array(count),sources=new Uint16Array(count),segments=new Uint32Array(count),buckets=Array.from({length:15},()=>[]),keep=lines.map(()=>[]),grid=new Map(),prefixes=lines.map(line=>line.name.includes('moving')?line.uuid:line.material.uuid),a=new THREE.Vector3(),b=new THREE.Vector3();let cursor=0,lastYield=performance.now(),removed=0,processed=0;
 const pause=async()=>{if(performance.now()-lastYield>7){await new Promise(resolve=>requestAnimationFrame(resolve));lastYield=performance.now();}};
 for(let li=0;li<lines.length;li++){const line=lines[li],positions=line.geometry.attributes.position;line.updateWorldMatrix(true,false);const matrix=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse).multiply(line.matrixWorld);for(let i=0;i<positions.count;i+=2){a.fromBufferAttribute(positions,i).applyMatrix4(matrix);b.fromBufferAttribute(positions,i+1).applyMatrix4(matrix);const id=cursor++,offset=id*4;sources[id]=li;segments[id]=i;if(a.z< -1||a.z>1||b.z< -1||b.z>1){keep[li].push(i,i+1);continue;}points[offset]=(a.x*.5+.5)*width;points[offset+1]=(-a.y*.5+.5)*height;points[offset+2]=(b.x*.5+.5)*width;points[offset+3]=(-b.y*.5+.5)*height;const length=Math.hypot(points[offset+2]-points[offset],points[offset+3]-points[offset+1]);lengths[id]=length;buckets[Math.max(0,Math.min(14,Math.floor(Math.log2(Math.max(.001,length)))+5))].push(id);if(id%1500===0)await pause();}}
 const cell=gap*2,key=(prefix,x,y)=>prefix+':'+x+':'+y;
 for(let bi=buckets.length-1;bi>=0;bi--)for(const id of buckets[bi]){const li=sources[id],o=id*4,x=points[o],y=points[o+1],ex=points[o+2],ey=points[o+3],length=lengths[id],dx=(ex-x)/Math.max(.0001,length),dy=(ey-y)/Math.max(.0001,length),theta=(Math.atan2(dy,dx)+Math.PI)%Math.PI,angle=Math.min(35,Math.floor(theta/(Math.PI/36))),prefix=prefixes[li],candidates=new Set();const gx=Math.floor((x+ex)/2/cell),gy=Math.floor((y+ey)/2/cell);for(let ix=-1;ix<=1;ix++)for(let iy=-1;iy<=1;iy++)for(const other of grid.get(key(prefix,gx+ix,gy+iy))??[])candidates.add(other);
  let covered=false;for(const other of candidates){const p=other*4,ox=points[p],oy=points[p+1],otherLength=lengths[other],ux=(points[p+2]-ox)/Math.max(.0001,otherLength),uy=(points[p+3]-oy)/Math.max(.0001,otherLength);if(length>otherLength*1.05||Math.abs(dx*ux+dy*uy)<.9986)continue;const d1=Math.abs((x-ox)*uy-(y-oy)*ux),d2=Math.abs((ex-ox)*uy-(ey-oy)*ux),t1=(x-ox)*ux+(y-oy)*uy,t2=(ex-ox)*ux+(ey-oy)*uy;if(d1<=gap&&d2<=gap&&Math.min(t1,t2)>=-gap&&Math.max(t1,t2)<=otherLength+gap){covered=true;break;}}
  if(covered)removed++;else{const segment=segments[id];keep[li].push(segment,segment+1);const samples=Math.max(1,Math.min(64,Math.ceil(length/gap)));for(let sample=0;sample<=samples;sample++){const t=sample/samples,k=key(prefix,Math.floor((x+(ex-x)*t)/cell),Math.floor((y+(ey-y)*t)/cell));if(!grid.has(k))grid.set(k,[]);const list=grid.get(k);if(list.at(-1)!==id)list.push(id);}}
  if((++processed&63)===0)await pause();
 }
 for(let li=0;li<lines.length;li++){lines[li].geometry.setIndex(keep[li]);lines[li].userData.sketchLineSpacingPx=gap;}
 return{inputSegments:count,removedSegments:removed,visibleSegments:count-removed,spacingPx:gap};
};
